INSERT INTO `v1_f3ecbb12f33902d5b36222f5bb4cd98fcd8f6063ef4df044dddb6915b8d7f058` VALUES (1, 15, "光属性ボーナスアップ", "光属性のキャラが４体以上編成されているとき、キャラの属性ボーナスが強化される。光属性と闇属性以外の属性ボーナスを無効化する。", 10101);
INSERT INTO `v1_f3ecbb12f33902d5b36222f5bb4cd98fcd8f6063ef4df044dddb6915b8d7f058` VALUES (1, 16, "闇属性ボーナスアップ", "闇属性のキャラが４体以上編成されているとき、キャラの属性ボーナスが強化される。光属性と闇属性以外の属性ボーナスを無効化する。", 10102);
INSERT INTO `v1_f3ecbb12f33902d5b36222f5bb4cd98fcd8f6063ef4df044dddb6915b8d7f058` VALUES (1, "damage_limit", "ダメージ減衰", "すべてのモンスターが一度の行動で受けるダメージ値を減衰させる。ダメージ値が上昇するほど減衰率も上昇する。", 10103);
